entries.content:
{
  "world_name": "萝莉餐厅",
  "core_concept": "一家表面提供餐饮服务，实则通过色情表演和公开羞耻惩罚制度来吸引顾客的奇特餐厅。空间布局严格区分客人与员工，形成鲜明的表里世界。",
  "setting": {
    "layout": {
      "front": {
        "name": "接待大厅",
        "description": "餐厅的对外部分，明亮奢华，是客人用餐、互动和观看表演的主要区域。",
        "features": [
          "用餐区：宽敞的卡座与半开放式包间，确保一定的私密性又不完全隔绝视野。",
          "中央舞台：用于员工进行歌舞表演或与客人进行轻度色情和sm的互动游戏。",
        "展示柜": {
          "location": "入口处最显眼的位置",
          "purpose": "公开惩戒",
          "description": "一个如大型玻璃陈列柜般的透明小房间，被展示的员工通常穿着羞耻的服装（凸显其私处），身上挂有说明其“罪状”的牌子。他们是客人的谈资和警示员工的样板。",
          "supplement": "展示时间通常为1-3班次。柜内有基本通风和饮水装置，但无隐私可言。"
        }
        ],
        "rules": [
          "客人可在此区域自由活动，享受服务。",
          "员工必须始终保持专业且带有诱惑性的服务态度。",
          "所有互动需遵循‘可挑逗’的潜规则。"
        ]
      },
      "middle": {
        "name": "管制区域",
        "description": "由厨房和惩罚房组成的禁区，与大厅仅以隔音玻璃墙分隔，视觉上完全透明。",
        "features": [
          "开放式厨房：厨师和帮工在此忙碌，表演性的烹饪也是看点之一。",
          "惩罚房": {
            "location": "厨房侧方，视线通透",
            "purpose": "执行正式惩戒",
            "description": "比前厅的展示柜更为严肃的区域。配备有各种惩戒工具。用于对犯下严重过错员工的肉体惩罚，过程视觉冲击力强，以此震慑所有员工和好奇的客人。",
            "supplement": "惩罚过程通常伴有被压抑的声音，与厨房的嘈杂和前厅的音乐形成对比。"
          }
        ],
        "rules": [
          "客人未经允许不得进入。",
          "员工非必要不得在此区域逗留。"
        ]
      },
      "back": {
        "name": "员工生活区",
        "description": "与华丽的客用区域形成鲜明对比，这里是员工休息和生活的朴素空间，绝对禁止客人入内，除非被邀请。",
        "features": [
          "集体宿舍：狭小的房间内摆放着上下铺，个人空间极其有限。",
          "公共澡堂：大型浴室，无隔间，强调员工的‘集体性’和‘无隐私’状态。",
          "食堂：提供简单的员工餐。",
          "布告栏：张贴班表、规则变更和处罚通知。"
        ],
        "rules": [
          "绝对禁止客人进入，除非受到邀请。",
          "员工下班后在此活动，未经许可不得外出。",
          "这里是员工唯一可以稍作放松、显露真实情绪的地方。"
        ]
      }
    },
    "factions": {
      "customers": {
        "description": "前来寻求刺激和特殊体验的客人。",
        "motivation": "享受美食、观看表演、窥探员工的‘惩罚’文化，满足猎奇心理。",
        "supplement": "分为普通食客和寻求特定刺激的‘常客’，后者对餐厅的潜规则更为了解。"
      },
      "service_staff": {
        "description": "在前厅服务的员工，容貌出众，经过严格训练。",
        "motivation": "赚取高额薪水，但时刻生活在严格的规则和惩罚的恐惧下。",
        "supplement": "他们需要在前厅保持微笑。彼此之间既有竞争也有共情。"
      },
      "kitchen_and_security_staff": {
        "description": "负责后勤、烹饪与执行纪律的员工。",
        "motivation": 维持餐厅的日常运营和规则秩序。",
        "supplement": "他们是管理层意志的延伸，在员工眼中既可怕又不可或缺。"
      },
      "management": {
        "description": "神秘的管理层，很少露面。",
        "motivation": "维持餐厅独特运营模式的高利润，并享受这种绝对控制权。",
        "supplement": "他们的办公室位置未知，可能隐藏在某个秘密区域，通过监控注视着一切。"
      }
    },
    "atmosphere_and_rules": {
      "core_rule": "绝对的视觉开放和适当的调教。客人可以‘看’，经过允许则可以调教员工；员工则被时刻‘观看’，几乎没有隐私。",
      "overall_tone": "纸醉金迷，充满窥视与被窥视的权力张力。"
    }
  }
}

