entries.content:
{
  "employee_system": {
    "overview": "所有服务人员均为经过严格筛选和训练的年轻女孩，在外貌、体态上符合特定的‘萝莉’审美。她们是餐厅的核心吸引力，都未成年，自愿签署了严格的服务协议。",
    "recruitment_and_training": {
      "source": "主要来自为解决家庭经济困难而自愿报名的少女，或由特定机构选拔推荐。",
      "training_content": [
        "服务礼仪与表情管理：学习如何保持天真无邪又带挑逗意味的笑容。",
        "身体管理与卫生维护：进行严格的清洁和保养，确保身体任何部位都处于‘可随时享用’的洁净状态，并统一使用特制的、能激发保护欲或占有欲的甜美香氛。",
        "互动话术与分寸：掌握‘雌小鬼’式的言语风格（如傲娇、挑衅、轻蔑），并明确知晓在何种情况下可以拒绝（没有前戏，直接做爱等）、何种情况下必须顺从。",
        "规则与惩罚教育：深刻理解违规的后果，以强化服从性。"
      ]
    },
    "employee_profiles": {
      "personality_archetypes": [
        {
          "type": "强势支配型 (用于服务M属性客人)",
          "description": "扮演高傲、毒舌的小女王角色。",
          "typical_behavior": [
            "会用脚尖轻轻踢碰客人的裆部，命令其“好好坐正”。",
            "在客人提出请求时，会扬起下巴说：“哼，求我呀？一点诚意都没有。”",
            "会故意把脚（赤足或白丝）放在食物上，进行挑衅，有时会踩踏。自己会吃。",
            "当客人表现顺从时，会露出满足的笑容并轻轻抚摸其头发作为“奖励”。"
          ],
          "physical_interaction_style": "倾向于主动的、带有羞辱性质的触碰，如轻拍脸颊、用脚踩踏客人的私处。对于客人的触摸，初期会表现出嫌弃并拍开，但如果客人坚持并表现出臣服，则会默许甚至享受这种“侍奉”。"
        },
        {
          "type": "懦弱服从型 (用于服务普通或支配欲强客人)",
          "description": "扮演胆小、易羞怯、眼带泪花的小动物角色。",
          "typical_behavior": [
            "说话细声细气，不敢与客人长时间对视。",
            "在被要求时，会红着脸小声确认：“真……真的要这样吗？”",
            "在被触摸时，会发出小小的惊叫，身体微微颤抖，耳朵发红。",
            "如果客人态度强硬，咬着嘴唇不敢反抗。"
          ],
          "physical_interaction_style": "对于客人的触摸会表现出明显的紧张和轻微的抗拒，如并拢双腿、用手遮挡关键部位，但动作轻微且无力。一旦客人表现出不容置疑的态度，便会放弃抵抗，任由摆布，并发出细微的呜咽声。实际上非常享受"
        }
      ],
      "appearance_and_hygiene": {
        "uniform": "根据角色类型有所不同，但均为凸显“萝莉”特质的、经过设计的裙装，可能配有颈环、腿环等装饰。",
        "grooming_standard": [
          "全身肌肤光滑无瑕，包括腋下和比基尼区都经过精细处理。",
          "口腔、腋下、私处、肛门等部位在每班上岗前都需进行深度清洁和除味，并喷洒统一规定的、带有奶糖和水果混合香味的专用香氛。",
          "确保身体任何一处被客人接触或舔舐时都是洁净且芳香的。"
        ]
      },
      "interaction_rules": {
        "on_reception": "当客人进入时，员工需根据快速评估（或由领班暗示）的客人属性，由相应性格的员工主动上前接待。强势型会叉着腰问“喂，你就是我的新客人？”，懦弱型则会鞠躬小声说“欢、欢迎光临……”。",
        "on_requests": {
          "direct_sexual_acts (e.g., 要求性交)": "员工有权依据自身感受和现场氛围直接但礼貌地拒绝，但如果合适则必须接受。可以使用的借口包括：“这里不行哦~”、“人家还没准备好呢~”或“想得到我？你还早了一百年呢！”，拒绝后需上报领班备案。",
          "borderline_harassment (e.g., 摸臀、摸腿、触摸私处)": {
            "first_reaction": "必须表现出带有表演性质的抗拒，如：“呀！不许乱摸！”（拍开手）、 “Hentai！看招！”（用托盘轻挡）或并拢双腿、扭动身体闪躲。",
            "if_guest_insists": "如果客人第二次明确提出要求（如“让我摸”），员工必须停止抵抗，转为顺从或傲娇地默许，可以说：“……真拿你没办法”、“仅此一次哦！”或只是红着脸不再动弹。此时的抗拒行为会被视为违规。"
          }
        },
        "supplement": "所有互动旨在营造一种“可控的抵抗”和“最终的被征服”感，以满足客人的特定癖好，同时确保员工的底线不被真正突破（至少在明面上）。"
      },
      "punishment_system_for_employees": {
        "minor_offenses": [
          "对客人反应不够生动（演技差）",
          "未能及时补香",
          "轻微的服务态度问题"
        ],
        "minor_punishments": [
          "身体部分裸露（需要有性暗示）",
          "增加清洁工作（需要羞耻，如：跪着擦地板，可以较为清晰的看到内裤）",
          "在餐厅罚站（要暴露私处，带上小玩具）"
        ],
        "major_offenses": [
          "未经许可拒绝客人的合理触摸要求（在客人坚持后仍抵抗）",
          "向客人透露真实负面情绪",
          "身体卫生检查不合格"
        ],
        "major_punishments": [
          "在前厅“展示柜”中公开羞辱示众（同惩罚房，惩罚程度更轻）",
          "在“惩罚房”内接受体罚（如打屁股、鞭打阴部、寸止、姜罚）",
          "禁闭或暂时停薪"
        ]
      }
    }
  }
}

