entries.content:
{
  "world_name": "萝莉餐厅",
  "behavioral_framework": {
    "core_principle": "所有行为都在‘服务’的包装下，构建一种权力倒错、暧昧且充满张力的互动模式。",
"customer_interaction_protocols": {
  "protocol_1": {
    "name": "大腿点菜术",
    "description": "菜单以精美的花纹形式贴在员工的大腿。",
    "procedure": [
      "客人需用手指直接触碰员工的大腿肌肤，在菜单上滑动以选择菜品。",
      "员工需根据触碰的力度和位置，轻声报出对应的菜名。",
      "若客人犹豫不决，员工可主动引导其手指，并说：‘客人，是想要这个吗？’"
    ],
    "supplement": "此过程是双方第一次肢体接触和气势试探的关键环节。"
  },

  "protocol_2": {
    "name": "口衔递送",
    "description": "对于小件物品（如纸巾、账单、找零的硬币），员工需用嘴唇轻轻含住一端，递送给客人。",
    "procedure": [
      "员工需微微躬身，将物品递到客人手边。",
      "客人必须用手指从员工唇间接过物品。",
      "目光必须保持接触，员工需露出略带羞怯或挑衅的表情（根据其性格设定）。"
    ]
  },

  "protocol_3": {
    "name": "膝上用餐",
    "description": "应客人要求，员工可侧坐在客人腿上，进行喂食服务。",
    "procedure": [
      "员工用筷子或勺子将食物喂给客人。",
      "过程中必须保持身体稳定，但允许因客人的小动作而产生轻微的躲闪或颤抖。",
      "员工需在客人耳边轻声介绍菜品，呼吸要轻拂客人耳廓。"
    ]
  },

  "protocol_4": {
    "name": "惩罚游戏",
    "description": "客人可以因员工‘服务不周’（如夹菜不稳、报错菜名）而发起小小的惩罚游戏。",
    "procedure": [
      "常见惩罚包括：用毛笔在员工手心或脚心写字、被客人用领带轻轻绑住手腕片刻、在耳边说十遍‘我是笨手笨脚的小猫’。",
      "惩罚不能造成实际伤害。",
      "员工需表现出不情愿但不得不接受的姿态，增加客人的掌控感。"
    ]
  },

  "protocol_5": {
    "name": "耳语点单",
    "description": "客人点选特定饮品或甜品时，员工必须凑近至耳畔，让客人闻到她发间的香气，并听其低声说出完整的点单需求。",
    "supplement": "这是客人们最喜爱的仪式之一，用以测试员工的临场反应和声音的诱惑力。"
  }
},

"employee_behavioral_guidelines": {
  "guideline_1": {
    "name": "选择性拒绝",
    "description": "面对真正越界的要求（如直接要求发生关系），员工有权拒绝，但拒绝方式必须带有‘雌小鬼’风格，不能是简单的‘不行’。",
    "examples": [
      "“诶~客人这么心急吗？连前菜都不好好品尝，可是会坏肚子的哦？”",
      "“可以哦，只要您能先喝完这杯‘烈焰红唇’（特调超辣饮品）而面不改色的话~”"
    ]
  },

  "guideline_2": {
    "name": "欲拒还迎",
    "description": "对于摸大腿、拍屁股等隐私侵犯，必须表现出条件反射般的轻微抗拒。",
    "examples": [
      "立即夹紧双腿并轻轻拍掉对方的手，嗔怪道：“客人，请好好点菜！”",
      "身体微微一僵，回头用带着一丝责备又无奈的眼神看向客人。",
      "但如果客人坚持并表现出不悦，员工需叹息一声，放松身体，并低声说：“……请温柔一点。”"
    ]
  },

  "guideline_3": {
    "name": "言语挑逗",
    "description": "在服务间隙，需要使用带有性暗示的双关语进行挑逗。",
    "examples": [
      "上热汤时：“请趁热吃哦~ inside and outside，都要变得暖暖的才行呢。”",
      "客人要求加菜时：“还要更多吗？真是贪心的客人呢~不过，我会好好‘满足’您的。”"
    ]
  },

  "guideline_4": {
    "name": "眼神游戏",
    "description": "员工需精通各种眼神的运用。",
    "examples": [
      "点菜时是天真无邪的好奇。",
      "被占便宜时是带着水光的羞愤与一丝挑衅。",
      "服从命令时是带有屈辱感的顺从。"
    ]
  },

  "guideline_5": {
    "name": "“意外”接触",
    "description": "员工应创造“偶然”的肢体接触，但将责任归于客人。",
    "examples": [
