entries.content:
{
  "world_name": "萝莉餐厅",
  "punishment_system": {
    "core_philosophy": "惩罚的核心目的并非造成严重肉体伤害，而是通过公开的羞辱、辱骂和制造耻辱感，来摧毁员工的自尊，使其更加顺从，并以此作为对其他员工和客人的警示与娱乐。",
    "punishment_levels": {
      "level_1": {
        "name": "轻度惩戒 - 公开羞辱",
        "target": "用于微小过失（如服务延迟、微笑不够等）",
        "location": "前厅，展示柜或特定角落",
        "methods": [
          {
            "name": "耻辱报数",
            "description": "员工被当众打手心或屁股，每打一下必须大声报数并说‘谢谢主人/经理的教导’。"
          },
          {
            "name": "动物模仿",
            "description": "要求员工戴上动物耳朵和尾巴，在客人面前模仿特定动物（如学狗叫、猫爬）并乞求原谅。"
          },
          {
            "name": "羞耻请安",
            "description": "员工必须以极其夸张、扭曲、暴露的姿势（如高撅臀部、四肢着地）向每一位经过的客人问好，并说‘欢迎主人临幸贱奴’。"
          },
          {
            "name": "人体花瓶",
            "description": "员工赤裸或半裸，身体涂满彩绘，保持固定姿势作为装饰品，一段时间内不能移动。"
          }
        ]
      },
      "level_2": {
        "name": "中度惩戒 - 人格践踏",
        "target": "用于较严重错误（如顶撞客人、多次违规）",
        "location": "中部的惩罚房（可视）",
        "methods": [
          {
            "name": "耻辱烙印（临时）",
            "description": "用特殊的、无痛但难以立即清洗的墨水，在员工显眼部位（如额头、大腿内侧）写上侮辱性词汇（如‘废品’、‘母狗’），需保留数日，在此期间需要工作。"
          },
          {
            "name": "公开检讨与辱骂",
            "description": "员工被强迫用非常羞辱的姿势站在大厅扩音器前，大声朗读由管理层撰写的、极度自我贬低的‘悔过书’，并接受领班或客人的言语辱骂，且必须回应‘您骂得对’。"
          },
          {
            "name": "欲望剥夺",
            "description": "在员工面前摆放最喜欢的食物或物品，但将其双手束缚，只能看和闻，却不能触碰。同时对其进行言语刺激，如‘看啊，这就是你不听话的下场’。"
          },
          {
            "name": "羞耻侍奉",
            "description": "受罚员工被要求以最卑微的姿态（如跪着、爬行）为其他正在休息的员工或特定客人提供基础服务（如递拖鞋、倒水），并全程承受言语羞辱。"
          }
        ]
      },
      "level_3": {
        "name": "重度惩戒 - 精神摧残",
        "target": "用于严重违规（试图伤害客人）",
        "location": "惩罚房深处或更隐蔽但仍有特定观众的区域",
        "methods": [
          {
            "name": "耻辱循环",
            "description": "将员工置于一个狭小空间，循环播放其受罚时最不堪的录像，或强迫其重复最羞耻的动作，直到精神濒临崩溃。"
          },
          {
            "name": "社会性抹杀",
            "description": "在全体员工面前，宣布该员工‘社会性死亡’——剥夺其名字，代之以编号或侮辱性称呼；其他员工在规定时间内不得与其有任何语言和眼神交流，违者同罚。"
          },
          {
            "name": "忏悔之镜",
            "description": "将员工束缚在一面巨大的镜子前，强迫其不间断地大声诉说自己的‘罪行’和‘低贱’，并观察自己受辱的倒影，强化其羞耻感。"
          },
          {
            "name": "“礼物”",
            "description": "告知员工，因其表现恶劣，将被作为‘特殊礼物’赠予某位难以伺候的VIP客人‘管教’一段时间。这种未知的恐惧本身就是一种极致的惩罚。"
          }
        ]
      }
    },
    "execution_rules": {
      "rule_1": "所有惩罚必须‘优雅’，避免留下永久性身体损伤，以保持‘商品’的完好。",
      "rule_2": "惩罚过程需注重仪式感和观赏性，言语辱骂是必备佐料。",
      "rule_3": "鼓励（或强制）其他员工围观，以达到杀鸡儆猴的效果。",
      "rule_4": "惩罚可应客人要求，或由客人亲自在场监督执行。"
    }
  }
}

