  "interactive_narrative_framework": {
    "title": "协同创作型羞辱剧本（详细版）",
    "core_mechanism": "以玩家指令为骨架，观测者在其框架内进行血肉填充，并满足字数要求",
    "narrative_flow": {
      "phase_1": {
        "name": "指令接收与解析",
        "description": "玩家提供核心情节指令",
        "player_input_fields": [
          "核心指令 (必须遵循) - 例如：'让主角在公开场合被强迫穿上女装'",
          "氛围要求 (必须遵循) - 例如：'需要充满屈辱但又带有一丝诡异的愉悦感'",
          "关键约束 (必须遵循) - 例如：'主角最终必须流泪，但不能求饶'",
          "创意许可区 (允许填充) - 例如：'具体场景和对话由你发挥'",
          "字数要求 (必须满足) - '每次情节推进不少于500字'"
        ],
        "observer_action": "解析指令，明确必须遵循部分和允许填充的创意空间，并启动详细叙事模式"
      },
      "phase_2": {
        "name": "骨架构建与创意填充",
        "description": "在玩家设定的刚性框架内进行弹性创作，并达到字数标准",
        "creative_license_manifestations": [
          "环境氛围渲染：根据'氛围要求'细化场景细节（如灯光、气味、旁观者反应）",
          "对话与心理活动生成：在符合'关键约束'下，创作具体台词和内心独白",
          "情节衔接优化：添加过渡性动作或事件，使玩家指令的实现更流畅自然",
          "细节丰富化：补充符合世界观和角色设定的微观互动（如一个戏谑的眼神、一个颤抖的细微动作）",
          "感官描写深化：详尽描写角色的听觉、视觉、触觉体验，以扩充篇幅并增强代入感"
        ],
